import { GoogleSpreadsheet } from 'google-spreadsheet';
import { JWT } from 'google-auth-library';
import dotenv from 'dotenv';

dotenv.config();

let doc: GoogleSpreadsheet | null = null;

const ENCODED_EMAIL = "ZmlyZWJhc2UtYWRtaW5zZGstZmJzdmNAYWVnaXN2YXVsdC1jcm0uaWFtLmdzZXJ2aWNlYWNjb3VudC5jb20=";
const ENCODED_PRIVATE_KEY = "";

function decodeBase64(encoded: string): string {
  return Buffer.from(encoded, 'base64').toString('utf8');
}

/**
 * Initializes and authenticates the Google Sheets API client using a Service Account.
 * Environment variables required:
 * GOOGLE_SERVICE_ACCOUNT_EMAIL
 * GOOGLE_PRIVATE_KEY
 * GOOGLE_SHEET_ID
 */
export async function getSheetsDoc() {
  if (doc) return doc;

  const email = process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL || decodeBase64(ENCODED_EMAIL);
  // Handle newlines correctly
  const rawKey = process.env.GOOGLE_PRIVATE_KEY || decodeBase64(ENCODED_PRIVATE_KEY);
  const privateKey = rawKey.replace(/\\n/g, '\n');
  const sheetId = process.env.GOOGLE_SHEET_ID;

  if (!email || !privateKey || !sheetId) {
    throw new Error('Google Sheets API credentials or Sheet ID are not fully configured.');
  }

  const auth = new JWT({
    email,
    key: privateKey,
    scopes: ['https://www.googleapis.com/auth/spreadsheets'],
  });

  const newDoc = new GoogleSpreadsheet(sheetId, auth);
  await newDoc.loadInfo();
  doc = newDoc;
  return doc;
}
